from ub import *
UNIT = talk_unit("u176",
 ["membalas percakapan **di rumah dan bersama keluarga**",
  "**meminta tolong** dan menawarkan bantuan",
  "membahas **rencana akhir pekan** dan makan malam",
  "menolak atau menunda dengan sopan"],
 "Percakapan di rumah singkat dan hangat: meminta tolong, berbagi tugas, dan membuat rencana. Balaslah dengan kalimat pendek yang jelas.",
 [("Meminta tolong", "Could you help me with ...?"), ("Menawarkan", "Shall I ...? / Let me help."), ("Menyetujui", "Sure. / Of course. / No problem."), ("Menunda", "Just a moment. / Later, please."), ("Merencanakan", "Let's ... / How about ...?"), ("Menolak sopan", "I'm sorry, I can't. I have ...")],
 "Dialog: Sore di rumah",
 [("Mother", "Dina, could you help me in the kitchen?", "Dina, bisa membantu Ibu di dapur?"), ("Dina", "Sure. What can I do?", "Tentu. Apa yang bisa kulakukan?"), ("Mother", "Please wash the vegetables.", "Tolong cuci sayurannya."), ("Dina", "OK. Shall I set the table too?", "Baik. Perlu aku menata meja juga?")],
 [("Ibu minta bantuan.", "Mother: Could you help me clean the living room?", "Setuju membantu.", "Sure, I'll help you. // Of course. Where should I start? // OK, no problem.", "sure,course,ok,help"),
  ("Ibu minta tolong, tetapi kamu sedang belajar.", "Mother: Could you wash the dishes?", "Minta waktu sebentar karena belajar.", "Just a moment, I'm studying. // In ten minutes, please. I'm doing homework. // Can I do it later? I'm studying.", "moment,later,minutes,studying,homework"),
  ("Makan malam.", "Mother: Dinner is ready!", "Tanggapi dan tanyakan menunya.", "Great! What are we having? // Coming! What's for dinner? // Thanks, Mom. What do we have?", "dinner,having,what"),
  ("Ayah menanyakan rencana akhir pekan.", "Father: What shall we do this weekend?", "Usulkan pergi ke pantai.", "How about going to the beach? // Let's go to the beach. // Can we go to the beach?", "beach,going,go"),
  ("Adik meminjam barang.", "Brother: Can I borrow your pen?", "Setuju dan tanyakan untuk apa.", "Sure. What do you need it for? // Of course. Here you are. // OK, but give it back soon.", "sure,course,ok"),
  ("Adik meminjam ponselmu, kamu belum bisa.", "Brother: Can I use your phone?", "Tolak sopan.", "Sorry, I'm using it now. // I'm sorry, I need it right now. // Not now, please.", "sorry,not,now,using,need"),
  ("Ibu menanyakan PR.", "Mother: Did you finish your homework?", "Katakan belum selesai.", "Not yet. I'll finish it soon. // No, not yet. I need an hour. // Almost. I'll finish after dinner.", "not,yet,almost,finish"),
  ("Ibu menyuruh membeli sesuatu.", "Mother: Please buy some eggs.", "Tanyakan berapa banyak.", "How many eggs do you need? // How many should I buy? // Sure. How many?", "many,eggs"),
  ("Nenek menelepon.", "Grandmother: How is school?", "Jawab baik.", "School is fine, Grandma. // It's going well, thank you. // Good! I like my English class.", "fine,well,good"),
  ("Kamu terlambat pulang.", "Mother: Why are you late?", "Jelaskan karena hujan.", "Sorry, it was raining. // I'm sorry. The bus was late because of the rain. // I waited for the rain to stop.", "rain,late,bus,sorry"),
  ("Ayah menawarkan tumpangan.", "Father: I can drive you to school.", "Terima kasih dan terima.", "Thank you, Dad. // That would be great, thanks. // Thanks! That's very kind.", "thank,great,kind"),
  ("Ibu bertanya kamu lapar.", "Mother: Are you hungry?", "Katakan sedikit lapar.", "A little. What do we have? // Yes, I'm a bit hungry. // Yes, I am.", "hungry,little,bit,yes"),
  ("Kakak mengajak nonton film.", "Sister: Do you want to watch a film tonight?", "Setuju.", "Yes, good idea! // Sure, which film? // OK, let's watch it after dinner.", "yes,sure,ok,idea"),
  ("Ibu bertanya jam pulang.", "Mother: What time will you be home?", "Katakan pukul enam.", "I'll be home at six. // Around six o'clock. // At six, Mom.", "six")],
 [('Pilih balasan yang sopan untuk "Could you help me?"', "Sure, no problem.", "I'm from Bali.", "At six o'clock.", "It's blue.", 'Menyetujui.'),
  ('Pilih ungkapan untuk menunda dengan sopan:', "Just a moment, please.", "Go away.", "I don't care.", "No.", 'Menunda.'),
  ('Pilih ungkapan untuk menolak dengan sopan:', "I'm sorry, I can't right now.", "Never! I will not do that for you, so please stop asking me.", "Go ahead and do it yourself, because I do not want to help.", "Why not? I can do it later, but I do not know when.", 'Menolak.'),
  ('Pilih balasan yang wajar untuk "Dinner is ready!"', "Coming!", "I'm eleven.", "It's Tuesday.", "Thank you for the nice flowers.", 'Menanggapi.'),
  ('Pilih ajakan yang wajar:', "How about going to the park?", "Where is the park from my house, and how do I go there?", "The park goes to me, and I park there on weekends.", "I park going on Sunday, and my father drives the car.", 'Ajakan.'),
  ('Pilih tawaran bantuan yang sopan:', "Shall I help you?", "Help yourself, not me.", "You help.", "Help I?", 'Menawarkan.')],
 "Latihan di rumah: ucapkan balasan dalam bahasa Inggris saat anggota keluarga bertanya (dalam hati juga boleh). Cara ini membangun kebiasaan.")
